<?php
require_once __DIR__.'/../includes/marketplace.php';
$user=require_login('provider');
$stmt=db()->prepare("SELECT p.* FROM providers p WHERE p.user_id=? LIMIT 1");$stmt->bind_param('i',$user['id']);$stmt->execute();$provider=$stmt->get_result()->fetch_assoc();if(!$provider){http_response_code(403);exit('Provider profile not found.');}
$profile=load_provider_matching_profile((int)$provider['id']);
$stmt=db()->prepare("SELECT tr.*,(SELECT COUNT(*) FROM provider_bids b WHERE b.trip_request_id=tr.id AND b.provider_id=?) bid_count,(SELECT MAX(b.created_at) FROM provider_bids b WHERE b.trip_request_id=tr.id AND b.provider_id=?) bid_created_at FROM trip_requests tr WHERE tr.status IN ('published','receiving_offers') AND (tr.expires_at IS NULL OR tr.expires_at>NOW()) ORDER BY tr.created_at DESC");$stmt->bind_param('ii',$provider['id'],$provider['id']);$stmt->execute();$result=$stmt->get_result();$requests=[];while($r=$result->fetch_assoc())$requests[]=enrich_provider_match($r,$provider,$profile);usort($requests,static fn(array $a,array $b):int=>$b['match_score']<=>$a['match_score']);
$page_title='Travel Requests';require __DIR__.'/../includes/header.php';
?><div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3">Travel requests</h1><p class="text-secondary mb-0">Open RFQs ranked for your matching profile.</p></div><a class="btn btn-outline-dark" href="/provider/dashboard.php">Dashboard</a></div><?php if($provider['verification_status']==='pending'):?><div class="alert alert-warning">Your provider account is pending verification. You can review requests, but bidding is enabled only for verified providers.</div><?php endif;?><div class="row g-3"><?php if(!$requests):?><div class="col-12"><div class="card p-4 text-secondary">No open requests right now.</div></div><?php else:foreach($requests as $r):$deadline=$r['expires_at']?strtotime($r['expires_at']):null;$hours=$deadline?max(0,round(($deadline-time())/3600,1)):null;?><div class="col-lg-6"><div class="card h-100 p-4"><div class="d-flex justify-content-between"><span class="badge text-bg-light"><?=e($r['request_number'])?></span><strong><?=$r['match_score']?>% match</strong></div><h2 class="h5 mt-3 mb-1"><?=e($r['origin']?:'India')?> → <?=e($r['destination'])?></h2><div class="text-secondary mb-3"><?=e((string)$r['start_date'])?> → <?=e((string)$r['end_date'])?> · <?=e((string)$r['adults'])?> adults</div><p class="mb-2"><?=e($r['description']?:'No additional requirements.')?></p><div class="fw-semibold mb-2"><?=e($r['currency'])?> <?=number_format((float)$r['budget_min'])?> – <?=number_format((float)$r['budget_max'])?></div><div class="small text-secondary mb-3"><?php if($hours!==null):?>Offer deadline: <?=$hours?> hrs remaining<?php else:?>No offer deadline set<?php endif;?></div><?php if($r['bid_count']):?><div class="alert alert-success py-2 mb-0">Offer submitted<?= $r['bid_created_at']?' · '.e($r['bid_created_at']):'' ?> · <a href="/provider/offers.php">Manage offer</a></div><?php elseif(in_array($provider['verification_status'],['verified','trusted','preferred'],true)):?><a class="btn btn-dark" href="/provider/request-view.php?id=<?=$r['id']?>">Review & respond</a><?php else:?><span class="text-secondary">Verification required to bid.</span><?php endif;?></div></div><?php endforeach;endif;?></div></div><?php require __DIR__.'/../includes/footer.php'; ?>